const { mkdtempSync, writeFileSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
if (!globalThis.input || typeof globalThis.input.html !== 'string') {
  throw new Error('Missing required input: html');
}
const tempDir = mkdtempSync(join(tmpdir(), 'topdf-'));
globalThis.htmlPath = join(tempDir, 'input.html');
globalThis.pdfPath = join(tempDir, globalThis.input.filename ? globalThis.input.filename : 'output.pdf');
writeFileSync(globalThis.htmlPath, globalThis.input.html, 'utf8');

